package com.nthexperience.desktop;
import org.junit.Test;import org.json.*;import java.util.*;import static org.junit.Assert.*;
public class ElevenMarketTest {
 @Test public void configurationIsBoundedAndCannotInjectMarkup(){String html=ElevenMarket.html(true,"</script><script>bad</script>","bogus");assertFalse(html.contains("bad</script>"));assertTrue(html.contains("AMEX:SPY"));assertTrue(html.contains("NASDAQ:QQQ"));assertTrue(html.contains("AMEX:DIA"));assertTrue(html.contains("\"dateRange\":\"1D\""));assertTrue(html.contains("World markets</span>"));assertTrue(html.contains("by TradingView"));assertTrue(html.contains("font-size:13px"));}
 @Test public void indexAndDarkRangeChoicesAreExplicit(){String html=ElevenMarket.html(false,"Indices","12M");assertTrue(html.contains("SP:SPX"));assertTrue(html.contains("NASDAQ:IXIC"));assertTrue(html.contains("TVC:DJI"));assertTrue(html.contains("\"colorTheme\":\"dark\""));assertTrue(html.contains("\"dateRange\":\"12M\""));assertFalse(html.contains("AMEX:SPY"));}
 @Test public void navigationRejectsPrivilegedAndNonWebSchemes(){for(String bad:Arrays.asList("file:///sdcard/private","javascript:alert(1)","intent://evil","http://example.com","https://user:secret@example.com","https://example.com:9999","https:///broken"))assertFalse(bad,ElevenMarket.safeLink(bad));assertTrue(ElevenMarket.safeLink("https://www.tradingview.com/symbols/AMEX-SPY/"));}
 @Test public void portableChoicesRejectUnsupportedTypesAndValues()throws Exception{Map<String,Object> values=new HashMap<>();values.put(ElevenMarket.MODE,"Indices");values.put(ElevenMarket.RANGE,"3M");ElevenMarket.validate(values);values.put(ElevenMarket.RANGE,3);try{ElevenMarket.validate(values);fail();}catch(JSONException expected){}values.put(ElevenMarket.RANGE,"1D");values.put(ElevenMarket.MODE,"Unlicensed provider");try{ElevenMarket.validate(values);fail();}catch(JSONException expected){}}
 @Test public void declaredCategoriesAndNthMappingsDoNotGuessUnknownApps(){assertEquals("Games",ElevenCategories.group("com.example/.Main",0));assertEquals("Productivity",ElevenCategories.group("com.example/.Main",7));assertEquals("Other",ElevenCategories.group("com.example/.Main",-1));assertEquals("Productivity",ElevenCategories.group("@notes",-1));assertEquals("Developer Tools",ElevenCategories.group("@powershell",-1));assertEquals("Utilities & Tools",ElevenCategories.group("@taskmanager",-1));}
}
